import React, { useState } from 'react';

function App() {
  const [message, setMessage] = useState('Нажми кнопку!');

  function handleClick() {
    setMessage('Ты нажал кнопку!');
  }

  return (
    <div>
      <h1>{message}</h1>
      <button onClick={handleClick}>Нажми меня</button>
    </div>
  );
}

export default App;
